808	/// CRIT-LUMEN-037/123: the store is the last boundary before persistence and must never trust a
809	/// caller's claim that an argument string is already safe -- it re-derives a redacted pattern
810	/// itself. Feeds a raw, unredacted string shaped like real private data (an email-looking commit
811	/// author flag value and a bare secret-looking positional token) and asserts neither survives.
812	#[test]
813	fn test_command_event_repository_redacts_raw_private_arguments_never_persisted_verbatim() {
814	    let dir = tempdir().unwrap();
815	    let db_path = Utf8PathBuf::from_path_buf(dir.path().join("command_event_redact_test.db")).unwrap();
816	    let store = SqliteStore::open(&db_path).unwrap();
817	    let conn = store.connection().unwrap();
818	
819	    let session_repo = SessionRepository::new(&conn);
820	    session_repo.upsert_session(&make_test_session_record("sess-cmd-redact")).unwrap();
821	
822	    let cmd_repo = CommandEventRepository::new(&conn);
